(() => {
  const ns = 'http://www.w3.org/1999/xhtml';
  const body = document.querySelector('body');
  if (!body) return;
  const svgRoot = document.documentElement;

  const head = document.createElementNS(ns, 'head');
  body.prepend(head);

  const htmlRoot = body.parentElement && body.parentElement.namespaceURI === ns
    ? body.parentElement
    : body;

  try {
    Object.defineProperty(document, 'head', {
      configurable: true,
      get() {
        return head;
      },
    });
  } catch {}

  try {
    Object.defineProperty(document, 'body', {
      configurable: true,
      get() {
        return body;
      },
    });
  } catch {}

  try {
    Object.defineProperty(document, 'documentElement', {
      configurable: true,
      get() {
        return htmlRoot;
      },
    });
  } catch {}

  try {
    Object.defineProperty(svgRoot, 'className', {
      configurable: true,
      get() {
        return svgRoot.getAttribute('class') || '';
      },
      set(value) {
        svgRoot.setAttribute('class', value || '');
      },
    });
  } catch {}

  const originalCreateElement = document.createElement.bind(document);
  document.createElement = function createElement(tagName, options) {
    return typeof tagName === 'string'
      ? document.createElementNS(ns, tagName, options)
      : originalCreateElement(tagName, options);
  };
})();
const headNodes = [
  { tag: 'meta', attrs: { charset: 'UTF-8' } },
  { tag: 'link', attrs: { rel: 'icon', type: 'image/svg+xml', href: '' } },
  { tag: 'meta', attrs: { name: 'viewport', content: 'initial-scale=1, width=device-width' } },
  { tag: 'link', attrs: { rel: 'modulepreload', href: './chunks/settingsStore.CQRFESJb.js', crossorigin: '' } },
];
for (const nodeDef of headNodes) {
  const node = document.createElement(nodeDef.tag);
  for (const [name, value] of Object.entries(nodeDef.attrs)) node.setAttribute(name, value);
  document.head.appendChild(node);
}
const title = document.createElement('title');
title.textContent = 'DogeUB';
document.head.appendChild(title);

const entryScript = document.createElement('script');
entryScript.type = 'module';
entryScript.setAttribute('crossorigin', '');
entryScript.src = './UqXob4bh.js';
document.body.appendChild(entryScript);

(function() {
  var STORAGE_KEY = 'doge_fog_enabled';
  var fogOn = localStorage.getItem(STORAGE_KEY) !== 'false';

  var iframe = document.createElement('iframe');
  iframe.id = 'fog-iframe';
  iframe.style.cssText = 'position:fixed;inset:0;z-index:0;pointer-events:none;border:none;opacity:' + (fogOn ? '1' : '0') + ';transition:opacity 0.5s ease;';
  iframe.srcdoc = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>body{margin:0;background:#000;overflow:hidden;width:100vw;height:100vh;}#fog{position:fixed;inset:0;}</style></head><body><div id="fog"></div><script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r134/three.min.js"><\/script><script src="https://cdn.jsdelivr.net/npm/vanta@latest/dist/vanta.fog.min.js"><\/script><script>new MutationObserver(function(){if(typeof VANTA!=="undefined"){VANTA.FOG({el:"#fog",highlightColor:0x444444,midtoneColor:0x222222,lowlightColor:0x111111,baseColor:0x000000});this.disconnect();}}).observe(document.head,{childList:true,subtree:true});<\/script></body></html>';
  document.body.prepend(iframe);

  window.addEventListener('keydown', function(e) {
    if (e.ctrlKey && e.altKey && (e.key === 'f' || e.key === 'F')) {
      e.preventDefault();
      fogOn = !fogOn;
      localStorage.setItem(STORAGE_KEY, fogOn);
      iframe.style.opacity = fogOn ? '1' : '0';
    }
  });
})();
